-- 용어 콘텐츠 2차 교정: 242개, 허용 다섯 필드만 변경.
-- 원본 문맥과 변경 대상 필드가 다르면 전체를 중단한다. 개인기록·코스·재화는 갱신하지 않는다.
BEGIN;
SET LOCAL lock_timeout = '10s';
DO $revision_v2$
DECLARE
  v_payload jsonb := pg_catalog.convert_from(pg_catalog.decode(
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
'' ||
