''
  , 'base64'), 'UTF8')::jsonb;
  v_item jsonb;
  v_current jsonb;
  v_word text;
  v_key text;
  v_expected jsonb;
  v_values jsonb;
  v_next public.words%ROWTYPE;
BEGIN
  IF pg_catalog.jsonb_array_length(v_payload) <> 242
     OR (SELECT count(DISTINCT (r->>'id')::integer) FROM pg_catalog.jsonb_array_elements(v_payload) r) <> 242 THEN
    RAISE EXCEPTION 'unexpected content revision size';
  END IF;
  IF (SELECT count(*) FROM public.words) <> 1233
     OR (SELECT count(*) FROM public.courses) <> 78
     OR (SELECT count(*) FROM public.course_words) <> 1234 THEN
    RAISE EXCEPTION 'dictionary or course size changed since review';
  END IF;
  -- 모든 원본을 확인하고 잠근 후에만 쓰기를 시작한다.
  FOR v_item IN SELECT value FROM pg_catalog.jsonb_array_elements(v_payload) LOOP
    SELECT w.word, pg_catalog.to_jsonb(w) INTO v_word, v_current
      FROM public.words w WHERE w.id = (v_item->>'id')::integer FOR UPDATE;
    IF NOT FOUND OR v_word IS DISTINCT FROM v_item->>'word' THEN
      RAISE EXCEPTION 'word identity changed: %', v_item->>'id';
    END IF;
    FOR v_key, v_expected IN SELECT key, value FROM pg_catalog.jsonb_each(v_item->'expected') LOOP
      IF (v_current->v_key) IS DISTINCT FROM v_expected THEN
        RAISE EXCEPTION 'reviewed content changed at word %, field %', v_item->>'id', v_key;
      END IF;
    END LOOP;
    IF EXISTS (SELECT 1 FROM pg_catalog.jsonb_object_keys(v_item->'values') k
               WHERE k NOT IN ('meaning','detailed_meaning','learning_example','news_example','visuals')) THEN
      RAISE EXCEPTION 'unexpected content column';
    END IF;
  END LOOP;
  FOR v_item IN SELECT value FROM pg_catalog.jsonb_array_elements(v_payload) LOOP
    v_values := v_item->'values';
    v_next := pg_catalog.jsonb_populate_record(NULL::public.words, v_values);
    UPDATE public.words w SET
      meaning = CASE WHEN v_values ? 'meaning' THEN v_next.meaning ELSE w.meaning END,
      detailed_meaning = CASE WHEN v_values ? 'detailed_meaning' THEN v_next.detailed_meaning ELSE w.detailed_meaning END,
      learning_example = CASE WHEN v_values ? 'learning_example' THEN v_next.learning_example ELSE w.learning_example END,
      news_example = CASE WHEN v_values ? 'news_example' THEN v_next.news_example ELSE w.news_example END,
      visuals = CASE WHEN v_values ? 'visuals' THEN v_next.visuals ELSE w.visuals END
      WHERE w.id = (v_item->>'id')::integer;
  END LOOP;
  FOR v_item IN SELECT value FROM pg_catalog.jsonb_array_elements(v_payload) LOOP
    SELECT pg_catalog.to_jsonb(w) INTO v_current FROM public.words w WHERE w.id = (v_item->>'id')::integer;
    FOR v_key, v_expected IN SELECT key, value FROM pg_catalog.jsonb_each(v_item->'values') LOOP
      IF (v_current->v_key) IS DISTINCT FROM v_expected THEN
        RAISE EXCEPTION 'content verification failed at word %, field %', v_item->>'id', v_key;
      END IF;
    END LOOP;
  END LOOP;
END;
$revision_v2$;
COMMIT;
SELECT 242 AS verified_words, (SELECT count(*) FROM public.words) AS word_count,
       (SELECT count(*) FROM public.courses) AS course_count,
       (SELECT count(*) FROM public.course_words) AS course_word_count;
